local SugarTongsMaker = {}
local PRODUCTS = {
    iron_sugartongs = { name = "Železni sladkorne klešče", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni sladkorne klešče za kuharje." },
    bronze_sugartongs = { name = "Bronast sladkorne klešče", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast sladkorne klešče za kuharje." },
    silver_sugartongs = { name = "Srebrn sladkorne klešče", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn sladkorne klešče za kuharje." },
    gilded_sugartongs = { name = "Pozlačen sladkorne klešče", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen sladkorne klešče za kuharje." },
    jewel_set_sugartongs = { name = "Draguljast sladkorne klešče", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast sladkorne klešče za kuharje." },
    royal_sovereign_sugartongs = { name = "Kraljevski suveren sladkorne klešče", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren sladkorne klešče z biseri za krono." },
}
local BUILDINGS = {
    sugartongs_workshop = { name = "Sugartongs delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    sugartongs_house = { name = "Sugartongs hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_sugartongs_atelier = { name = "Mojstrski sugartongs atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_sugartongs_palace = { name = "Suverena sugartongs palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
SugarTongsMaker.ironStock=16; SugarTongsMaker.bronzeStock=12; SugarTongsMaker.woodStock=12; SugarTongsMaker.leatherStock=8; SugarTongsMaker.silverStock=8; SugarTongsMaker.goldStock=6; SugarTongsMaker.jewelStock=4; SugarTongsMaker.pearlStock=4
SugarTongsMaker.productStock = {}; SugarTongsMaker.buildings = {}; SugarTongsMaker.maker = nil; SugarTongsMaker.activeMaking = {}; SugarTongsMaker.totalProducts = 0; SugarTongsMaker.dayTimer = 0
function SugarTongsMaker.init() SugarTongsMaker.ironStock=16; SugarTongsMaker.bronzeStock=12; SugarTongsMaker.woodStock=12; SugarTongsMaker.leatherStock=8; SugarTongsMaker.silverStock=8; SugarTongsMaker.goldStock=6; SugarTongsMaker.jewelStock=4; SugarTongsMaker.pearlStock=4; SugarTongsMaker.productStock={}; SugarTongsMaker.buildings={}; SugarTongsMaker.maker=nil; SugarTongsMaker.activeMaking={}; SugarTongsMaker.totalProducts=0; SugarTongsMaker.dayTimer=0; print("[SugarTongsMaker] Royal Sugar Tongs Maker System initialized (6 products, 4 buildings)") end
function SugarTongsMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SugarTongsMaker.maker={name=n or ("Sladkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sladkar najet: %s (spretnost: %d)",SugarTongsMaker.maker.name,s),"success") end; return true end
function SugarTongsMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SugarTongsMaker.build(id) local ok,e=SugarTongsMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SugarTongsMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SugarTongsMaker.getQualityBonus() local b=0; for _,bd in ipairs(SugarTongsMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SugarTongsMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SugarTongsMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and SugarTongsMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and SugarTongsMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and SugarTongsMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and SugarTongsMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SugarTongsMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SugarTongsMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SugarTongsMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SugarTongsMaker.buildings==0 then return false,"Potrebna sladkarska delavnica" end; if not SugarTongsMaker.maker then return false,"Potreben sladkar" end; return true end
function SugarTongsMaker.make(pt,qty) qty=qty or 1; local ok,e=SugarTongsMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SugarTongsMaker.ironStock=SugarTongsMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then SugarTongsMaker.bronzeStock=SugarTongsMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then SugarTongsMaker.woodStock=SugarTongsMaker.woodStock-d.woodCost*qty end; if d.leatherCost then SugarTongsMaker.leatherStock=SugarTongsMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then SugarTongsMaker.silverStock=SugarTongsMaker.silverStock-d.silverCost*qty end; if d.goldCost then SugarTongsMaker.goldStock=SugarTongsMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SugarTongsMaker.jewelStock=SugarTongsMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SugarTongsMaker.pearlStock=SugarTongsMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SugarTongsMaker.maker then t=math.max(1,t-math.floor(SugarTongsMaker.maker.skill/13)) end; table.insert(SugarTongsMaker.activeMaking,{id="sugartongs_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SugarTongsMaker.completeMaking(m) local q=1.0+(SugarTongsMaker.getQualityBonus()/100); if SugarTongsMaker.maker then q=q+(SugarTongsMaker.maker.skill/140) end; q=math.min(2.5,q); SugarTongsMaker.productStock[m.productType]=(SugarTongsMaker.productStock[m.productType] or 0)+m.quantity; SugarTongsMaker.totalProducts=SugarTongsMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SugarTongsMaker.maker then SugarTongsMaker.maker.itemsMade=SugarTongsMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SugarTongsMaker.maker.skill=math.min(100,SugarTongsMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sladkor izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"sugartongs.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function SugarTongsMaker.update(dt) if not _G.state then return end; SugarTongsMaker.dayTimer=SugarTongsMaker.dayTimer+dt; if SugarTongsMaker.dayTimer>=30 then SugarTongsMaker.dayTimer=0; for i=#SugarTongsMaker.activeMaking,1,-1 do local m=SugarTongsMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SugarTongsMaker.completeMaking(m); table.remove(SugarTongsMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SugarTongsMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SugarTongsMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SugarTongsMaker.getStats() return {ironStock=SugarTongsMaker.ironStock,bronzeStock=SugarTongsMaker.bronzeStock,woodStock=SugarTongsMaker.woodStock,leatherStock=SugarTongsMaker.leatherStock,silverStock=SugarTongsMaker.silverStock,goldStock=SugarTongsMaker.goldStock,jewelStock=SugarTongsMaker.jewelStock,pearlStock=SugarTongsMaker.pearlStock,productStock=SugarTongsMaker.productStock,numBuildings=#SugarTongsMaker.buildings,hasMaker=SugarTongsMaker.maker~=nil,makerName=SugarTongsMaker.maker and SugarTongsMaker.maker.name or "—",makerSkill=SugarTongsMaker.maker and SugarTongsMaker.maker.skill or 0,activeMaking=#SugarTongsMaker.activeMaking,totalProducts=SugarTongsMaker.totalProducts} end
return SugarTongsMaker
